<?php declare(strict_types=1); ?>
<article class="directory-unit" data-directory-unit data-directory-search="<?= e(DirectoryPagination::searchText($unit,$admin)) ?>" data-unit-id="<?= (int)$unit['id'] ?>" data-type="<?= e($unit['node_type']) ?>" data-zone="<?= e($unit['zone_name'] ?? '') ?>"><div class="directory-unit-heading"><span class="directory-unit-icon" aria-hidden="true"><?= $unit['node_type']==='zone'?'◫':($unit['node_type']==='area'?'♧':'✧') ?></span><div><span class="chip"><?= e(ucfirst($unit['node_type'])) ?></span><h3><?= e($unit['node_name']) ?></h3><span class="directory-code"><?= e($unit['parish_code'] ?? 'Unit #'.$unit['id']) ?></span></div></div><dl><div><dt>Parent</dt><dd><?= e($unit['parent_name'] ?? 'Provincial treasury') ?></dd></div><div><dt>Zone</dt><dd><?= e($unit['zone_name'] ?? '—') ?></dd></div><?php if($admin && (!empty($unit['contact_person']) || !empty($unit['phone_number']))): ?><div><dt>Contact</dt><dd><?= e(trim(($unit['contact_person'] ?? '').' '.($unit['phone_number'] ?? ''))) ?></dd></div><?php endif ?></dl><?php if($admin): ?><div class="directory-unit-actions"><a class="secondary" data-directory-action="edit" href="<?= e($directory->url(['edit_unit'=>(int)$unit['id']],'hierarchy-editor')) ?>" aria-label="Edit <?= e($unit['node_name']) ?>">Edit details</a><a class="delete-link" data-directory-action="delete" href="<?= e($directory->url(['delete_unit'=>(int)$unit['id']],'delete-unit')) ?>" aria-label="Review deletion of <?= e($unit['node_name']) ?>">Delete</a></div><?php endif ?></article>
